#!/usr/bin/env python3
import sys

def fibonacci(n):
    """Generate the first n Fibonacci numbers starting from 1, 1."""
    if n <= 0:
        return []
    elif n == 1:
        return [1]
    else:
        fibs = [1, 1]
        for _ in range(2, n):
            fibs.append(fibs[-1] + fibs[-2])
        return fibs

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 fib.py <n>")
        sys.exit(1)

    try:
        n = int(sys.argv[1])
        result = fibonacci(n)
        for num in result:
            print(num)
